package com.samanramezani1377.woogit.data.repository
import com.samanramezani1377.woogit.core.domain.entity.EntityId
import com.samanramezani1377.woogit.core.domain.entity.StoreId
import com.samanramezani1377.woogit.core.domain.error.CoreResult
import com.samanramezani1377.woogit.core.domain.error.fold
import com.samanramezani1377.woogit.core.domain.model.*
import com.samanramezani1377.woogit.core.domain.repository.*
import com.samanramezani1377.woogit.data.network.*
import kotlinx.datetime.Instant
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import java.security.MessageDigest
private val mutationJson=Json{ignoreUnknownKeys=true;explicitNulls=false}
private fun payloadHash(value:String)=MessageDigest.getInstance("SHA-256").digest(value.toByteArray()).joinToString(""){ "%02x".format(it) }
@Serializable private data class OrderMutation(val status:String)
private fun WooOrderTypedDto.toDomain()=Order(EntityId(id.toString()),when(status){"pending"->OrderStatus.PENDING;"processing"->OrderStatus.PROCESSING;"on-hold"->OrderStatus.ON_HOLD;"completed"->OrderStatus.COMPLETED;"cancelled"->OrderStatus.CANCELLED;"refunded"->OrderStatus.REFUNDED;"failed"->OrderStatus.FAILED;else->OrderStatus.OTHER},customer_id.takeIf{it!=0L}?.let{Customer(EntityId(it.toString()),listOfNotNull(billing?.first_name,billing?.last_name).joinToString(" "),billing?.phone)},billing?.let{Address(it.first_name,it.last_name,it.company,it.address_1,it.address_2,it.city,it.state,it.postcode,it.country,it.phone)},shipping?.let{Address(it.first_name,it.last_name,it.company,it.address_1,it.address_2,it.city,it.state,it.postcode,it.country,it.phone)},Payment(payment_method,payment_method_title,transaction_id,payment_method!=null),shipping_lines.map{ShippingLine(it.method_id,it.method_title,it.total)},coupon_lines.map{Discount(it.code,it.discount)},emptyList(),line_items.map{OrderItem(EntityId(it.id.toString()),it.product_id.takeIf{v->v!=0L}?.let{v->EntityId(v.toString())},it.variation_id.takeIf{v->v!=0L}?.let{v->EntityId(v.toString())},it.name,it.quantity,it.subtotal,it.total)},date_modified_gmt?.let(Instant::parse),number.ifBlank{id.toString()},total,currency)
class OrderRepositoryV1Impl(private val local:LocalOrderDataSource<Order>,private val provider:WooCommerceClientProvider,private val coordinator:MutationCoordinator,private val pending:PendingOperationRepository):OrderRepository{
 override suspend fun get(storeId:StoreId,id:EntityId):CoreResult<Order>{val cached=local.get(storeId,id);return provider.client(storeId).fold({(store,api)->api.order(store.baseUrl,id.value.toLong()).fold({remote->val d=remote.toDomain();local.upsert(storeId,d);CoreResult.Success(d)},{cached})},{cached})}
 override suspend fun list(storeId:StoreId,page:Int,perPage:Int,search:String?,status:String?):CoreResult<List<Order>>{val cached=if(page==1)local.list(storeId)else null;return provider.client(storeId).fold({(store,api)->api.orders(store.baseUrl,page,perPage,search,status).fold({values->val d=values.map(WooOrderTypedDto::toDomain);d.forEach{local.upsert(storeId,it)};CoreResult.Success(d)},{cached?:CoreResult.Failure(mapError(it))})},{cached?:CoreResult.Failure(mapError(it))})}
 override suspend fun update(storeId:StoreId,id:EntityId,order:Order):CoreResult<Order>{val payload=mutationJson.encodeToString(OrderMutation(order.status.name.lowercase()));val hash=payloadHash(payload);val op=PendingOperation(EntityId("order-update-${storeId.value}-${id.value}-${hash.take(16)}"),storeId,"order",id,OperationType.UPDATE,payload,hash,0,null,null);val localResult=coordinator.execute(op){local.upsert(storeId,order).let{if(it is CoreResult.Success)CoreResult.Success(order)else CoreResult.Failure((it as CoreResult.Failure).error)}};if(localResult is CoreResult.Failure)return localResult;return provider.client(storeId).fold({(store,api)->api.updateOrder(store.baseUrl,id.value.toLong(),WooOrderTypedDto(id.value.toLong(),number=order.number,status=order.status.name.lowercase(),total=order.total?:"0",currency=order.currency?:"",customer_id=order.customer?.id?.value?.toLongOrNull()?:0L)).fold({remote->val d=remote.toDomain();local.upsert(storeId,d);pending.markSucceeded(op.id);CoreResult.Success(d)},{if(it is HttpApiException&&it.statusCode in 408..599)CoreResult.Success(order)else CoreResult.Failure(mapError(it))})},{CoreResult.Success(order)})}
}
private fun mapError(error:Throwable)=when(error){is HttpApiException->when(error.statusCode){401->com.samanramezani1377.woogit.core.domain.error.DomainError.Authentication("Authentication failed");403->com.samanramezani1377.woogit.core.domain.error.DomainError.Permission("Permission denied");404->com.samanramezani1377.woogit.core.domain.error.DomainError.NotFound("remote",error.statusCode.toString());409->com.samanramezani1377.woogit.core.domain.error.DomainError.Conflict("Remote conflict");422->com.samanramezani1377.woogit.core.domain.error.DomainError.Validation("Validation failed");429->com.samanramezani1377.woogit.core.domain.error.DomainError.RateLimited("Rate limited");in 500..599->com.samanramezani1377.woogit.core.domain.error.DomainError.Server("Server error");else->com.samanramezani1377.woogit.core.domain.error.DomainError.Unknown("HTTP ${error.statusCode}")};else->com.samanramezani1377.woogit.core.domain.error.DomainError.Network(error.message?:"Network failure")}
